from pathlib import Path
from zipfile import ZipFile
import hashlib,datetime,json
R=Path(__file__).resolve().parents[1];old=json.loads((R/'data/downloads.json').read_text());ice=json.loads((R/'data/ice-shelf-download.json').read_text())
items=[('countries.zip','Admin 0 Countries','5.1.1','https://naturalearth.s3.amazonaws.com/50m_cultural/ne_50m_admin_0_countries.zip','https://www.naturalearthdata.com/downloads/50m-cultural-vectors/50m-admin-0-countries-2/'),('regions.zip','Geographic Regions Polygons','5.0.0','https://naturalearth.s3.amazonaws.com/50m_physical/ne_50m_geography_regions_polys.zip','https://www.naturalearthdata.com/downloads/50m-physical-vectors/50m-physical-labels/'),('ice-shelves.zip','Antarctic Ice Shelves Polygons','4.1.0','https://naturalearth.s3.amazonaws.com/50m_physical/ne_50m_antarctic_ice_shelves_polys.zip','https://www.naturalearthdata.com/downloads/50m-physical-vectors/50m-antarctic-ice-shelves/')]
manifest=[]
for name,title,version,url,page in items:
 p=R/'data/raw'/name;z=ZipFile(p);v=z.read(next(x for x in z.namelist() if x.endswith('.VERSION.txt'))).decode().strip();assert v==version
 meta=old.get(name,ice if name=='ice-shelves.zip' else {});retrieved=meta.get('retrieved_at_utc',datetime.datetime.fromtimestamp(p.stat().st_mtime,datetime.timezone.utc).isoformat())
 manifest.append({'filename':name,'publisher':'Natural Earth','title':title,'embedded_version':version,'resolution':'1:50 million','download_url':url,'source_page':page,'retrieved_at_utc':retrieved,'retrieval_timestamp_basis':'download response log' if meta else 'download file completion mtime','bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'terms':'Public domain','terms_url':'https://www.naturalearthdata.com/about/terms-of-use/','attribution':'Made with Natural Earth','coverage':'Global generalized country/territory polygons' if name=='countries.zip' else 'Physical region labels, used only to trace the Eurasian divider' if name=='regions.zip' else 'Perennial Antarctic shelves; source lineage 2003–04 Mosaic of Antarctica; seasonal sea ice excluded','limitations':'Generalized de facto boundaries, not legal or survey geometry' if name=='countries.zip' else 'Approximate physical-region boundaries, not universal continental definitions' if name=='regions.zip' else 'Historical ice extent, not a current ice-front survey; download page says 4.0.0 but archive VERSION.txt says 4.1.0'})
(R/'source-manifest.json').write_text(json.dumps({'sources':manifest,'geographic_definitions':'config.json and data/processed/continents/component-membership.json','course':'https://github.com/weitzman-musa/30DayMapChallenge','stage':'Feasibility draft; independent published-area crosschecks remain for final audit'},indent=2))
print('Frozen checksums and embedded versions recorded.')
